const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]);
  const region = nyc.buffer(20000); // 20km radius around NYC

  // MODIS 8-day composite: need to find the composite covering July 20-27
  // MOD11A2 composites every 8 days starting from a reference date
  const target2016Start = '2016-07-20';
  const target2016End = '2016-07-27';

  const baseline2001Start = '2001-07-20';
  const baseline2001End = '2001-07-27';
  const baseline2010Start = '2010-07-27';
  const baseline2010End = '2010-08-05';

  // 2. Data Acquisition
  const modis = ee.ImageCollection('MODIS/006/MOD11A2');

  // Get 2016 data
  const lst2016 = modis
    .filterDate(target2016Start, target2016End)
    .filterBounds(region)
    .select('LST_Day_1km');

  console.log('2016 Collection size:', lst2016.size().getInfo());

  if (lst2016.size().getInfo() === 0) {
    console.log('No data for 2016 July 20-27.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get 2001-2010 baseline (all years, same period)
  const lstBaseline = ee.ImageCollection(
    ee.List.sequence(2001, 2010).map(function(year) {
      return modis
        .filterDate(ee.Date.fromYMD(year, 7, 20), ee.Date.fromYMD(year, 7, 28))
        .filterBounds(region)
        .select('LST_Day_1km')
        .mean();
    })
  );

  console.log('Baseline years collection size:', lstBaseline.size().getInfo());

  if (lstBaseline.size().getInfo() === 0) {
    console.log('No baseline data for 2001-2010.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing
  const img2016 = lst2016.mean().multiply(0.02); // Scale factor to Kelvin
  const imgBaseline = lstBaseline.mean().multiply(0.02);

  // Check pixel counts
  const count2016 = img2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countBaseline = imgBaseline.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log('2016 valid pixels:', count2016);
  console.log('Baseline valid pixels:', countBaseline);

  if (count2016 === 0 || countBaseline === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate mean temperatures
  const temp2016 = img2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const tempBaseline = imgBaseline.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log('2016 July 20-27 LST (K):', temp2016 ? temp2016.toFixed(2) : 'null');
  console.log('2001-2010 baseline LST (K):', tempBaseline ? tempBaseline.toFixed(2) : 'null');

  // 5. Validation & Final Answer
  if (temp2016 === null || tempBaseline === null || 
      temp2016 < 250 || temp2016 > 350 || 
      tempBaseline < 250 || tempBaseline > 350) {
    console.log('Invalid temperature values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const diff = temp2016 - tempBaseline;
  console.log('Temperature difference (2016 - baseline):', diff.toFixed(2), 'K');

  if (temp2016 > tempBaseline) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
